bool isVec4NaN(vec4 v) { 
    return isnan(v.x) || isnan(v.y) || isnan(v.z) || isnan(v.w); 
}

struct HITINFO{
    vec3 point;
    vec3 normal;
    bool didhit;
    float dist;
    float steps;
};

vec4 quaternionSquared(vec4 Q) {
    return vec4(Q.x*Q.x - Q.y*Q.y - Q.z*Q.z - Q.w*Q.w, 2.0*Q.x*Q.y, 2.0*Q.x*Q.z, 2.0*Q.x*Q.w);
}

float juliasetDE(vec4 z, vec4 c) {
    int maxiterations = 100;

    vec4 zn = z;
    float sqdzndz0length = 1.0;

    for(int i = 0; i < maxiterations; i++) {
        sqdzndz0length = 4.0 * dot(zn,zn) * sqdzndz0length;
        zn = quaternionSquared(zn) +c;

        if(dot(zn,zn) > 4.0) {
            break;
        }
    }

    float distanceEstimation = 0.25*log(dot(zn,zn))*sqrt(dot(zn,zn)/sqdzndz0length);
    return distanceEstimation;
}

vec3 juliasetnormal(vec4 z, vec4 c) {
    float dx = 0.001;
    float dy = 0.001;
    float dz = 0.001;
    float dfdx = (juliasetDE(z+vec4(dx,0.0,0.0,0.0), c) - juliasetDE(z-vec4(dx,0.0,0.0,0.0), c))/(2.0*dx);
    float dfdy = (juliasetDE(z+vec4(0.0,dy,0.0,0.0), c) - juliasetDE(z-vec4(0.0,dy,0.0,0.0), c))/(2.0*dy);
    float dfdz = (juliasetDE(z+vec4(0.0,0.0,dz,0.0), c) - juliasetDE(z-vec4(0.0,0.0,dz,0.0), c))/(2.0*dz);

    vec3 normal = normalize( vec3(dfdx, dfdy, dfdz) );
    return normal;
}

HITINFO RAYCASTJULIASET(vec4 c, vec3 O, vec3 D, float W) {
    float t = 0.0;
    vec3 P = O;
    for(int i = 0; i < 800; i++) {
        float d =  juliasetDE(vec4(P,W), c);
        t += d;
        P = P+D*d;
        if(d < 0.0001) {
            HITINFO hitinfo;
            hitinfo.point = P;
            hitinfo.normal = juliasetnormal(vec4(P,W),c);
            hitinfo.dist = t;
            hitinfo.didhit = true;
            hitinfo.steps = float(i);
            return hitinfo;
        }
        else if(t > 10.0) break;
    }
    HITINFO hitinfo;
    hitinfo.didhit = false;
    hitinfo.dist = t;
    hitinfo.steps = 300.0;
    return hitinfo;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv = uv*2.0-1.0;
    uv.x *= iResolution.x / iResolution.y;

    mat3 rotation = mat3(cos(iTime),0.0, -sin(iTime),
                         0.0,       1.0,  0.0,
                         sin(iTime),0.0,  cos(iTime));


    vec3 D = rotation * normalize(vec3(uv, 2.0));
    vec3 O = rotation * vec3(0.0,0.0,-3.0);

    vec4 C = vec4(-0.4,0.6,0.4,0.1);


    HITINFO hitinfo = RAYCASTJULIASET(C,O,D, 0.0);

    vec3 col = hitinfo.normal.yyy*0.3+0.7;
    if(hitinfo.didhit == true) {
        col *= vec3(0.8,0.6,0.4);
        col *= 20.0/hitinfo.steps;
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
